SELECT * FROM emp
WHERE NOT EXISTS (
  SELECT 1 FROM emp ee WHERE ee.job = emp.job AND ee.sal = 34
);

WITH dept_min AS (
  SELECT name, min(deptno) AS min_deptno FROM dept GROUP BY name
)
SELECT e.* FROM emp e
JOIN dept_min d ON e.job = d.name
WHERE e.empno > d.min_deptno;
